<?php
if (!defined('ABSPATH')) exit;

/* Editorial expansion: evergreen, store-owned guides without external-source
 * claims. Runs once and keeps the home journal supplied with fresh content. */
add_action('init', function () {
    if (get_option('bhc_editorial_pack_v1_done')) return;
    $posts = [
        ['راهنمای انتخاب یخچال برای آشپزخانه‌های کوچک', 'یخچال کوچک باید هم از نظر ابعاد با مسیر ورود و کابینت هماهنگ باشد و هم فضای داخلی قابل استفاده‌ای داشته باشد.', ['پیش از خرید عرض، عمق و ارتفاع محل نصب را اندازه بگیرید.','جهت بازشدن در و فاصله لازم برای گردش هوا را بررسی کنید.','ظرفیت را بر اساس الگوی خرید خانواده انتخاب کنید، نه فقط عدد درج‌شده روی جعبه.']],
        ['راهنمای خرید جاروبرقی برای خانه‌های پررفت‌وآمد', 'برای انتخاب جاروبرقی، فقط به توان موتور نگاه نکنید؛ نوع فیلتر، صدای کار، وزن و دسترسی به قطعات مصرفی هم در استفاده روزانه مهم‌اند.', ['برای خانه دارای کودک یا حیوان خانگی، فیلتر قابل شست‌وشو و سری مناسب را جدی بگیرید.','طول سیم و شعاع عملکرد را با متراژ خانه مقایسه کنید.','هزینه و دسترسی کیسه، فیلتر و برس جایگزین را پیش از خرید بپرسید.']],
        ['چطور ظرفیت ماشین لباسشویی را درست انتخاب کنیم؟', 'ظرفیت مناسب لباسشویی به تعداد اعضای خانواده، فاصله بین شست‌وشوها و نوع لباس‌هایی که می‌شویید بستگی دارد.', ['ظرفیت بیشتر همیشه به معنی مصرف کمتر نیست؛ برنامه و مقدار بار واقعی اهمیت دارد.','فضای بازشدن در، عمق دستگاه و مسیر حمل را اندازه‌گیری کنید.','برنامه‌های کاربردی و امکان شست‌وشوی سریع را با نیاز روزمره خود تطبیق دهید.']],
        ['راهنمای انتخاب تلویزیون بر اساس فاصله تماشا', 'اندازه تلویزیون باید با فاصله نشستن، وضوح تصویر و نوع استفاده هماهنگ باشد تا تصویر درخشان اما خسته‌کننده نشود.', ['فاصله مبل تا دیوار را پیش از انتخاب اندازه صفحه ثبت کنید.','اگر بازی یا محتوای سریع می‌بینید، نرخ نوسازی و تأخیر ورودی را بررسی کنید.','تعداد ورودی‌ها، جای نصب و مسیر کابل‌کشی را از ابتدا در نظر بگیرید.']],
        ['قبل از خرید لوازم خانگی چه اندازه‌هایی را ثبت کنیم؟', 'بسیاری از مشکلات نصب از انتخاب نادرست مدل شروع نمی‌شوند؛ از اندازه‌گیری ناقص مسیر ورود و محل نصب شروع می‌شوند.', ['عرض در ورودی، راهرو، آسانسور و پیچ‌های مسیر را یادداشت کنید.','برای تهویه، بازشدن درها و اتصال برق یا آب فضای آزاد لازم را کنار بگذارید.','اندازه‌ها را همراه با عکس محل برای مشاور فروشگاه ارسال کنید.']],
        ['چک‌لیست تحویل سالم لوازم خانگی', 'تحویل کالا پایان خرید نیست. بررسی ظاهری، مدل، اقلام همراه و شرایط ضمانت باید پیش از امضای رسید انجام شود.', ['نام کامل مدل و رنگ را با سفارش و پلاک کالا تطبیق دهید.','بدنه، درها، نمایشگر، لوازم جانبی و بسته‌بندی را در حضور تحویل‌گیرنده بررسی کنید.','هر ایراد یا مغایرت را همان زمان در رسید یا گزارش تحویل ثبت کنید.']],
    ];
    $created = 0;
    foreach ($posts as $row) {
        if (get_page_by_title($row[0], OBJECT, 'post')) continue;
        $html = '<p>'.esc_html($row[1]).'</p><h2>نکته‌های مهم</h2><ul>';
        foreach ($row[2] as $item) $html .= '<li>'.esc_html($item).'</li>';
        $html .= '</ul><h2>جمع‌بندی</h2><p>در بهاران‌هوم، انتخاب کالا باید بر اساس اطلاعات همان مدل، شرایط واقعی فضا و نیاز روزمره انجام شود. اگر درباره ابعاد، امکانات یا وضعیت موجودی مطمئن نیستید، پیش از ثبت سفارش از مشاور فروشگاه راهنمایی بگیرید.</p>';
        $id = wp_insert_post(['post_title'=>$row[0], 'post_content'=>$html, 'post_status'=>'publish', 'post_type'=>'post', 'post_excerpt'=>$row[1], 'comment_status'=>'closed'], true);
        if (is_wp_error($id) || !$id) continue;
        update_post_meta($id, '_bhb_editorial_review', 'approved');
        update_post_meta($id, '_bhc_seo_title', $row[0].' | راهنمای بهاران‌هوم');
        update_post_meta($id, '_bhc_seo_description', $row[1].' راهنمای کاربردی بهاران‌هوم برای انتخاب مطمئن و متناسب با خانه.');
        $term = get_term_by('name', 'راهنمای خرید', 'category');
        if (!$term) $term = wp_insert_term('راهنمای خرید', 'category');
        if (!is_wp_error($term)) wp_set_post_categories($id, [(int)($term->term_id ?? $term['term_id'])]);
        $created++;
    }
    update_option('bhc_editorial_pack_v1_done', ['created'=>$created, 'at'=>current_time('mysql')], false);
}, 28);
